$screenHref = static function(string $target): string {
    $parts = explode('&', $target); $page = array_shift($parts); $query = ['page'=>$page];
    foreach($parts as $part){$kv=explode('=',$part,2);$query[$kv[0]]=$kv[1]??'';}
    return '?'.http_build_query($query);
};
$sectionTitle = static function(string $title, string $module, string $description=''): void {
    echo '<div class="screen-title"><div><span class="eyebrow">'.esc(strtoupper($module)).'</span><h1>'.esc($title).'</h1>'.($description?'<p>'.esc($description).'</p>':'').'</div><span class="prototype-chip">UI MOCKUP · SAMPLE DATA</span></div>';
};
$label = static function(string $title, string $value, string $hint='') { echo '<label class="mock-field"><span>'.esc($title).'</span><div>'.esc($value).'</div>'.($hint?'<small>'.esc($hint).'</small>':'').'</label>'; };
$action = static function(string $text, string $target, string $style='primary') use ($screenHref) { echo '<a class="mock-button '.esc($style).'" href="'.esc($screenHref($target)).'">'.esc($text).'</a>'; };
$table = static function(array $headers, array $rows): void {
    echo '<div class="mock-table-wrap"><table class="mock-table"><thead><tr>'; foreach($headers as $h) echo '<th>'.esc($h).'</th>'; echo '</tr></thead><tbody>';
    foreach($rows as $row){echo '<tr>';foreach($row as $cell)echo '<td>'.$cell.'</td>';echo '</tr>';}
    echo '</tbody></table></div>';
};
